def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict
    cache = OrderedDict()  # key -> [value, expire_time]
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # purge expired entries as of current time t
            expired_keys = [k for k, v in cache.items() if v[1] <= t]
            for k in expired_keys:
                del cache[k]
            if key in cache:
                cache[key][0] = value
                cache[key][1] = t + ttl
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = [value, t + ttl]
        else:  # get
            _, t, key = op
            expired_keys = [k for k, v in cache.items() if v[1] <= t]
            for k in expired_keys:
                del cache[k]
            if key in cache:
                results.append(cache[key][0])
                cache.move_to_end(key)
            else:
                results.append(-1)
    return results

